package storage

import "time"

// Subscription is a user-built standalone subscription (ferry-sub-filters, decided by the user on 2026-11-21):
// one user may create several, each with its own token, filter dimensions (region/labels/protocol) and
// per-sub config (remark_template/sort/max_nodes/include_rtt).
// Filter/Config are JSON text (strict validation on the writing side, see sub.ParseFilter/ParseConfig);
// the delivering side parses and applies them in memory; Token is generated by the server with crypto/rand (same policy as RandomToken).
type Subscription struct {
	ID        uint      `gorm:"primaryKey" json:"id"`
	UserID    uint      `gorm:"index" json:"user_id"`
	Token     string    `gorm:"size:64;uniqueIndex" json:"token"`
	Name      string    `gorm:"size:64" json:"name"`
	Filter    string    `gorm:"type:text" json:"filter"`
	Config    string    `gorm:"type:text" json:"config"`
	Enabled   bool      `gorm:"default:true" json:"enabled"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}
